import time


def grade(inputs):
    chain = GRADE_PROMPT | llm_model.chain("low", structured=GradeDocument)
    for attempt in range(3):
        try:
            return chain.invoke(inputs)
        except Exception:
            time.sleep(2 ** attempt)
    raise RuntimeError("grading failed")

